def blob(data):return hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()
for name,spec in updates.items():
 p=Path(name);raw=p.read_bytes()
 if blob(raw)==spec['after']:continue
 if blob(raw)!=spec['before']:raise RuntimeError('Source changed: '+name)
 lines=raw.decode().splitlines(keepends=True)
 for start,end,text in reversed(spec['edits']):lines[start:end]=[text]
 result=''.join(lines).encode()
